{"t":"edge","id":"e-orders-dts","from":"orders-db","to":"dts-sync","label":"CDC"}
{"t":"node","id":"warehouse","product":"maxcompute","label":"MaxCompute Warehouse","group":"sg","why":"Stores historical data and runs nightly batch analytics."}
{"t":"edge","id":"e-dts-warehouse","from":"dts-sync","to":"warehouse","label":"replicate"}
{"t":"node","id":"lake","product":"oss","label":"Data Lake OSS","group":"sg","why":"Landing zone for raw files and external table storage."}
{"t":"edge","id":"e-lake-warehouse","from":"lake","to":"warehouse","label":"ingest"}
{"t":"node","id":"scheduler","product":"dataworks","label":"DataWorks Scheduler","group":"sg","why":"Orchestrates nightly ETL jobs and data integration tasks."}
{"t":"edge","id":"e-scheduler-warehouse","from":"scheduler","to":"warehouse","label":"batch jobs","kind":"control"}
{"t":"node","id":"serving","product":"hologres","label":"Hologres Serving","group":"sg","why":"Real-time OLAP engine serving dashboard queries fast."}
{"t":"edge","id":"e-warehouse-serving","from":"warehouse","to":"serving","label":"load"}
{"t":"node","id":"dashboards","product":"quick-bi","label":"Quick BI Dashboards","group":"sg","why":"Business users explore data via interactive reports."}
{"t":"edge","id":"e-serving-dashboards","from":"serving","to":"dashboards","label":"query"}
{"t":"node","id":"logs","product":"sls","label":"SLS Logs","group":"sg","why":"Centralizes pipeline logs and monitoring alerts."}
{"t":"edge","id":"e-warehouse-logs","from":"warehouse","to":"logs","kind":"control"}
{"t":"done","summary":"MySQL orders replicated via DTS to MaxCompute, scheduled by DataWorks, served through Hologres to Quick BI dashboards."}

{"t":"say","text":"I'll connect your Singapore data center to Alibaba Cloud via Express Connect and set up a phased VM migration path."}
